const rows = [["a", 1], ["b", 0], ["c", 3], ["d", 2]];
let out = "";

scan: for (const [name, count] of rows) {
  for (const step of [1, 2, 3]) {
    if (count === 0) continue scan;
    if (step > count) break;
    if (name === "d") break scan;
    out += name;
  }

  out += "-";
}

console.log(out);
